import java.util.*;

class Solution {
    public int subsetXorSum(int[] nums) {
        int orAll = 0;
        for (int x : nums) orAll |= x;           // bits that appear anywhere
        return orAll << (nums.length - 1);       // each such bit is on in 2^(n-1) subsets
    }
}

